import{Z as t,e as s,f as a,a0 as i}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Save and Continue Later","description":"","frontmatter":{},"headers":[],"relativePath":"guides/submissions-workflows/save-and-continue-later.md","filePath":"guides/submissions-workflows/save-and-continue-later.md","lastUpdated":1782912477000}'),n={name:"guides/submissions-workflows/save-and-continue-later.md"};function o(r,e,l,p,d,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="save-and-continue-later" tabindex="-1">Save and Continue Later <a class="header-anchor" href="#save-and-continue-later" aria-label="Permalink to &quot;Save and Continue Later&quot;">​</a></h1><p>Long and multi-page forms lose completions when visitors get interrupted. Formie stores incomplete submissions in the database, optionally exposes a save button with resume links, and can restore in-progress state automatically when someone returns. This walkthrough configures the feature end-to-end for a job application or registration form.</p><h2 id="prepare-an-application-form" tabindex="-1">Prepare an Application Form <a class="header-anchor" href="#prepare-an-application-form" aria-label="Permalink to &quot;Prepare an Application Form&quot;">​</a></h2><p>You need an installed Formie site, permission to edit forms, and access to <code>config/formie.php</code> if you want to change retention. Create a form named <strong>Job Application</strong> with handle <code>jobApplication</code>. Add Name and Email Address fields to the first page and a Multi-Line Text field named <strong>Experience</strong> to the second. Save it, then create <code>templates/apply.twig</code>:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;jobApplication&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>Open <code>/apply</code> and confirm the first page appears. The steps below configure this form. <a href="/forms/save-continue-later">Save &amp; Continue Later</a> explains the feature, and <a href="/get-started/configuration">Configuration</a> lists the retention options.</p><h2 id="two-related-behaviours" tabindex="-1">Two Related Behaviours <a class="header-anchor" href="#two-related-behaviours" aria-label="Permalink to &quot;Two Related Behaviours&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>User-visible?</th></tr></thead><tbody><tr><td><strong>Incomplete submissions</strong></td><td>Saves progress as users move through pages</td><td>Automatic on multi-page forms</td></tr><tr><td><strong>Save button + resume link</strong></td><td>Lets users deliberately save and return via URL</td><td>Optional per page</td></tr></tbody></table><p>Both store real submission records marked incomplete until the final step completes.</p><h2 id="step-1-—-enable-multi-page-or-long-single-page-form" tabindex="-1">Step 1 — Enable Multi-Page or Long Single-Page Form <a class="header-anchor" href="#step-1-—-enable-multi-page-or-long-single-page-form" aria-label="Permalink to &quot;Step 1 — Enable Multi-Page or Long Single-Page Form&quot;">​</a></h2><p>Save and continue is useful for:</p><ul><li>Multi-page forms (progress saved on each page navigation)</li><li>Long single-page forms with many fields</li></ul><p>Ensure <strong>Enable Multi-Page Forms</strong> is on globally unless you intentionally run single-page only (<strong>Settings</strong> or <code>enableMultiPageForms</code> in config).</p><h2 id="step-2-—-automatic-submission-state" tabindex="-1">Step 2 — Automatic Submission State <a class="header-anchor" href="#step-2-—-automatic-submission-state" aria-label="Permalink to &quot;Step 2 — Automatic Submission State&quot;">​</a></h2><p>On the form <strong>Settings</strong> tab, enable <strong>Restore In-Progress Submissions Automatically</strong> when visitors should resume an in-progress submission if they return to the same form URL in the same browser session (without a resume link).</p><ul><li><strong>Enabled</strong> — Formie restores the incomplete submission on return</li><li><strong>Disabled</strong> — Form starts fresh unless the user opens a resume link</li></ul><p>Automatic state uses database-backed submission state.</p><h2 id="step-3-—-add-a-save-button" tabindex="-1">Step 3 — Add a Save Button <a class="header-anchor" href="#step-3-—-add-a-save-button" aria-label="Permalink to &quot;Step 3 — Add a Save Button&quot;">​</a></h2><p>On the page where users should be able to save deliberately:</p><ol><li>Open page settings in the form builder</li><li>Enable <strong>Show Save Button</strong></li><li>Set <strong>Save Button Label</strong> (for example <code>Save and finish later</code>)</li><li>Choose link vs button display if your template supports it</li></ol><p>When clicked, Formie creates a <strong>resume link</strong> with a token tied to that in-progress submission. The link works across browsers and devices — treat it like private access to a draft, especially for forms collecting personal data.</p><blockquote><p>Anyone with a resume link can continue that in-progress submission.</p></blockquote><h2 id="step-4-—-configure-retention" tabindex="-1">Step 4 — Configure Retention <a class="header-anchor" href="#step-4-—-configure-retention" aria-label="Permalink to &quot;Step 4 — Configure Retention&quot;">​</a></h2><p>Align plugin settings with how long users might wait before returning:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>saveResumeTokenTtlDays</code></td><td>14</td><td>How long resume links stay valid</td></tr><tr><td><code>maxIncompleteSubmissionAge</code></td><td>30</td><td>When incomplete submissions are removed by scheduled cleanup</td></tr><tr><td><code>submissionStateRetentionDays</code></td><td>30</td><td>Retention for front-end submission state</td></tr><tr><td><code>maxSavedDraftsPerSession</code></td><td>10</td><td>Saved drafts per browser session</td></tr></tbody></table><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;saveResumeTokenTtlDays&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;maxIncompleteSubmissionAge&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;submissionStateRetentionDays&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Also review the form&#39;s <strong>Data Retention</strong> settings under form builder <strong>Settings</strong> for completed submission cleanup — separate from incomplete retention.</p><h2 id="step-5-—-submission-statuses-for-incomplete-records" tabindex="-1">Step 5 — Submission Statuses for Incomplete Records <a class="header-anchor" href="#step-5-—-submission-statuses-for-incomplete-records" aria-label="Permalink to &quot;Step 5 — Submission Statuses for Incomplete Records&quot;">​</a></h2><p>Incomplete submissions appear in the control panel like other submissions, usually with an incomplete flag. Filter and report on them using <a href="/submissions/submission-statuses">Submission Statuses</a>.</p><p>Consider a status workflow for teams reviewing abandoned applications — for example, <strong>Incomplete</strong> → <strong>Follow up</strong> → <strong>Complete</strong>.</p><h2 id="step-6-—-email-notifications" tabindex="-1">Step 6 — Email Notifications <a class="header-anchor" href="#step-6-—-email-notifications" aria-label="Permalink to &quot;Step 6 — Email Notifications&quot;">​</a></h2><p>By default, notifications fire on <strong>complete</strong> submissions. Decide whether partial saves should trigger email:</p><ul><li>Usually <strong>no</strong> — wait for final submit</li><li>If partial saves must send an email, implement a custom workflow task for that action. Ordinary notification dispatch skips incomplete submissions before evaluating notification conditions; adding a condition cannot enable partial-save delivery. See <a href="/guides/submissions-workflows/adding-a-custom-workflow-task-from-scratch">Custom Workflow Tasks</a>.</li></ul><p>Avoid spamming admins on every page step unless that is intentional.</p><h2 id="step-7-—-headless-and-graphql" tabindex="-1">Step 7 — Headless and GraphQL <a class="header-anchor" href="#step-7-—-headless-and-graphql" aria-label="Permalink to &quot;Step 7 — Headless and GraphQL&quot;">​</a></h2><p>Save-and-resume works for client-rendered forms when using Formie&#39;s client session model. Bootstrap via <code>formieClientForm</code>; partial saves flow through <code>submitFormieClientForm</code> with incomplete state.</p><p>Resume links point at your Craft front-end URL with a token query parameter — ensure your SPA or Twig template loads the form and passes the token to Formie&#39;s client bootstrap.</p><h2 id="step-8-—-security-and-privacy" tabindex="-1">Step 8 — Security and Privacy <a class="header-anchor" href="#step-8-—-security-and-privacy" aria-label="Permalink to &quot;Step 8 — Security and Privacy&quot;">​</a></h2><ul><li>Resume links are capability URLs — do not log them in analytics or expose them in referrer headers to third parties</li><li>Set TTL short enough for your compliance requirements</li><li>On GDPR-sensitive forms, document save-and-continue in your privacy notice</li><li>Hiding the save button does not prevent partial storage: multi-page navigation still saves incomplete submissions. Automatic restoration controls whether progress is loaded again, not whether it is stored. If answers must only be stored on final submission, use a single-page form without a save button and test its actual submission workflow, including any custom tasks.</li></ul><h2 id="test-saving-and-returning" tabindex="-1">Test Saving and Returning <a class="header-anchor" href="#test-saving-and-returning" aria-label="Permalink to &quot;Test Saving and Returning&quot;">​</a></h2><p>Enter a test name and email, then move to the Experience page. Check <strong>Formie → Submissions</strong>, including incomplete records: the first page’s answers should be saved even before you use the save button. Enter some experience, save deliberately and copy the resume link.</p><p>Open the resume link in a separate browser session. Confirm that the saved answers load, finish the application, and check that the record is complete. Your normal notification should send after completion, not after the intermediate save. Treat the copied link as private and remove your test submission afterward.</p><p>If the resume link cannot load the draft, check whether the link expired or retention cleanup removed its submission. Disabling automatic restoration should stop a bare visit from restoring progress, while a valid resume link should still work.</p>`,43)])])}const m=t(n,[["render",o]]);export{c as __pageData,m as default};
